mapper.select:
SELECT t.* FROM forum_tags t
INNER JOIN forum_post_tags fpt ON t.id = fpt.tag_id
WHERE fpt.post_id = #{postId}

mapper.update:
UPDATE forum_post_tags fpt INNER JOIN forum_posts p ON p.id = fpt.post_id
SET fpt.tag_id = #{newTagId}
WHERE fpt.tag_id = #{oldTagId} AND p.author_username = #{username}
